// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    address admin;

    function setUp() public {
        c = new Owned();
        admin = address(this);
    }

    function testFuzz_property(address caller, address _owner) public {
        vm.assume(caller != admin);
        vm.prank(caller);
        (bool success, ) = address(c).call(abi.encodeWithSelector(c.setOwner.selector, _owner));
        assertTrue(!success);
    }
}
